// One lead per posting. The board name comes from the item that fetched it.
// `places`, `description` and `salary_mentions` are working fields for later steps
// (hard filters, Jev, Claude). Apply hard filters removes them before saving.
const now = new Date().toISOString();
const leads = [];

// Ashby states pay as components (Salary, EquityCashValue, Commission, Bonus...).
// Only base salary in USD, per year or per month, counts toward the pay floor.
// Anything else (other currencies, other intervals, no salary) is unknown pay.
const PER_YEAR = { '1 YEAR': 1, '1 MONTH': 12 };
function usdBasePay(comp) {
  if (!comp) return { min: null, max: null };
  const components = (comp.summaryComponents || [])
    .concat((comp.compensationTiers || []).flatMap((t) => t.components || []));
  const salary = components.filter((c) =>
    c.compensationType === 'Salary' && c.currencyCode === 'USD' && PER_YEAR[c.interval] &&
    (typeof c.minValue === 'number' || typeof c.maxValue === 'number'));
  if (!salary.length) return { min: null, max: null };
  const k = (c) => PER_YEAR[c.interval];
  const mins = salary.map((c) => (typeof c.minValue === 'number' ? c.minValue : c.maxValue) * k(c));
  const maxes = salary.map((c) => (typeof c.maxValue === 'number' ? c.maxValue : c.minValue) * k(c));
  return { min: Math.min(...mins), max: Math.max(...maxes) };
}

function place(text, address) {
  const a = (address && address.postalAddress) || {};
  return {
    text: String(text || '').trim(),
    country: String(a.addressCountry || '').trim(),
    region: String(a.addressRegion || '').trim(),
    locality: String(a.addressLocality || '').trim(),
  };
}

// Posting text as plain text: Ashby's descriptionPlain, or descriptionHtml with tags removed.
function plainText(job) {
  if (job.descriptionPlain) return String(job.descriptionPlain);
  return String(job.descriptionHtml || '')
    .replace(/<\s*(br|\/p|\/li|\/h\d|\/div)\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
}

// The description sent to Jev and Claude. Unrelated text lowers Jev's accuracy, so the
// benefits and equal-opportunity text that usually follows the role is cut, blank lines
// are collapsed, and the rest is capped at DESCRIPTION_MAX characters.
const DESCRIPTION_MAX = 6000;
const BOILERPLATE_START = /^\W*(benefits|perks|what we offer|our benefits|equal (employment )?opportunity)\b|is an equal (employment )?opportunity employer/i;
function trimDescription(text) {
  const lines = text.split('\n').map((l) => l.replace(/\s+/g, ' ').trim());
  const kept = [];
  let length = 0;
  for (const line of lines) {
    if (length > 800 && BOILERPLATE_START.test(line)) break;
    if (!line && (!kept.length || !kept[kept.length - 1])) continue;
    kept.push(line);
    length += line.length + 1;
  }
  let out = kept.join('\n').trim();
  if (out.length > DESCRIPTION_MAX) {
    out = out.slice(0, DESCRIPTION_MAX).replace(/\s+\S*$/, '') + ' …';
  }
  return out;
}

// Dollar amounts in the full description that could be a yearly salary, such as
// "$150,000 - $190,000" or "$160K–$200K", each with the line it appears in. Jev later
// picks the base salary among them (or none), only for postings with no structured pay.
const AMOUNT = String.raw`\$\s?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\$\s?\d{2,3}(?:\.\d+)?\s?[kK]\b`;
const AMOUNT_TO = String.raw`\$?\s?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\$?\s?\d{2,3}(?:\.\d+)?\s?[kK]\b`;
const SALARY_SPAN = new RegExp(`(?:${AMOUNT})(?:\\s*USD)?(?:\\s*(?:-|–|—|to)\\s*(?:${AMOUNT_TO})(?:\\s*USD)?)?`, 'g');
function amounts(span) {
  return (span.match(/\d[\d,]*(?:\.\d+)?\s?[kK]?/g) || []).map((a) => {
    const n = parseFloat(a.replace(/,/g, ''));
    return /k$/i.test(a.trim()) ? n * 1000 : n;
  });
}
function salaryMentions(text) {
  const out = [];
  const seen = new Set();
  for (const line of text.split('\n')) {
    for (const m of line.matchAll(SALARY_SPAN)) {
      const span = m[0].trim();
      const values = amounts(span);
      const max = Math.max(...values);
      if (seen.has(span) || max < 30000 || max > 2000000) continue;
      seen.add(span);
      out.push({ span, context: line.replace(/\s+/g, ' ').trim().slice(0, 300) });
    }
  }
  return out.slice(0, 10);
}

$input.all().forEach((item, i) => {
  const jobs = item.json.jobs;
  if (!Array.isArray(jobs)) return; // this board's fetch failed; the other boards still run
  const board = $('Split boards').itemMatching(i).json.board;

  for (const job of jobs) {
    if (job.isListed === false) continue;
    const pay = usdBasePay(job.compensation);
    const places = [place(job.location, job.address)]
      .concat((job.secondaryLocations || []).map((l) => place(l.location, l.address)))
      .filter((p) => p.text || p.country || p.region || p.locality);
    const text = plainText(job);
    leads.push({
      json: {
        lead_key: 'ashby:' + board + ':' + job.id,
        ats: 'ashby',
        board: board,
        job_id: job.id,
        company: board,
        title: job.title,
        location_text: job.location || '',
        workplace_type: job.workplaceType || '',
        secondary_locations: (job.secondaryLocations || [])
          .map((l) => l.location)
          .filter(Boolean)
          .join('; '),
        pay_text: (job.compensation && job.compensation.compensationTierSummary) || '',
        pay_min: pay.min,
        pay_max: pay.max,
        posting_url: job.jobUrl,
        apply_url: job.applyUrl,
        published_at: job.publishedAt || null,
        last_seen_at: now,
        places: places,
        description: trimDescription(text),
        salary_mentions: salaryMentions(text),
      },
    });
  }
});

return leads;

// One Telegram message per picked lead, in fit order. Parse mode is HTML, so escape
// posting text. The fit line is Claude's reply for the lead at the same position; if
// Claude failed, the message goes out without it.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// location_basis comes from Apply hard filters: us_remote, metro or unclear.
function where(lead) {
  const stated = [lead.location_text, lead.workplace_type].filter(Boolean).join(' · ');
  if (lead.location_basis === 'unclear') return 'Location unclear' + (stated ? ' (' + stated + ')' : '');
  if (lead.location_basis === 'us_remote' && !/remote/i.test(stated)) return stated + ' · Remote (US) option';
  return stated || 'Location unclear';
}

function pay(lead) {
  if (lead.pay_text) return lead.pay_text;
  if (lead.pay_extracted_text) return lead.pay_extracted_text + ' (from the description)';
  return 'Pay not listed';
}

// "Fit 84 · role 25 · stack 16 · seniority 15 · location 15 · domain 7 · fresh 6"
function breakdown(lead) {
  const p = lead.points || {};
  const parts = [['role', p.roleFamily], ['stack', p.stack], ['seniority', p.seniority],
    ['location', p.location], ['domain', p.domain], ['fresh', p.freshness]];
  if (p.referral) parts.push(['referral', p.referral]);
  return ['Fit ' + lead.fit_score].concat(parts.map(([name, v]) => name + ' ' + (v || 0))).join(' · ');
}

// Claude's reply as one clean line, or null.
function fitLine(reply) {
  const text = reply && typeof reply.merged_response === 'string' ? reply.merged_response
    : ((reply && reply.content) || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
  const line = String(text || '').replace(/\s+/g, ' ').trim().replace(/^["“]|["”]$/g, '');
  return line || null;
}

const replies = $input.all();
return $('Pick leads to send').all().map(({ json: lead }, i) => {
  const line = fitLine(replies[i] && replies[i].json);
  const lines = [
    '<b>' + esc(lead.title) + '</b>',
    esc(lead.company),
    'Location: ' + esc(where(lead)),
    'Pay: ' + esc(pay(lead)),
    breakdown(lead),
  ];
  if (line) lines.push('<i>' + esc(line) + '</i>');
  if (lead.published_at) lines.push('Posted: ' + String(lead.published_at).slice(0, 10));

  return {
    json: {
      row_id: lead.id,
      lead_key: lead.lead_key,
      fit_score: lead.fit_score,
      fit_line: line,
      text: lines.join('\n'),
      silent: true,
      button_text: 'Open posting',
      button_url: lead.posting_url,
    },
  };
});

// Hard rules from Job Scout config: location, pay floor, excluded titles.
// Every posting is checked on every scan, so a config change also applies to
// leads saved earlier. The first rule a lead breaks goes in filter_result
// ("location", "pay_floor" or "excluded_title"); a lead that breaks none gets
// "passed". Unknown pay or location never breaks a rule.
// The department and team fields are never used: DevRel roles often sit in Marketing.
const cfg = $('Job Scout config').first().json;
const rules = cfg.locationRules || {};
const payFloor = Number(cfg.payFloor) || 0;

// Case-insensitive match on whole words, so "Finance" doesn't match "Fintech".
function wordsRx(list) {
  const terms = (list || []).map((t) => String(t).trim()).filter(Boolean);
  if (!terms.length) return null;
  const alt = terms
    .map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+'))
    .join('|');
  return new RegExp('(?<![\\p{L}\\p{N}])(?:' + alt + ')(?![\\p{L}\\p{N}])', 'iu');
}
const has = (rx, s) => Boolean(rx && s && rx.test(s));

const US_STATES = new Set(('AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS ' +
  'MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY').split(' '));
// Only used when a location has no address country.
const NON_US_TEXT = wordsRx(['Canada', 'UK', 'United Kingdom', 'Europe', 'EMEA', 'EU', 'European Union',
  'APAC', 'LATAM', 'Latin America', 'Asia', 'India', 'Australia', 'Mexico', 'Brazil', 'Germany',
  'France', 'Spain', 'Ireland', 'Netherlands', 'Poland', 'Portugal', 'Japan', 'Singapore', 'Israel',
  'London', 'Berlin', 'Toronto']);
const REMOTE = wordsRx(['remote']);
const usNames = rules.usCountryNames || ['United States', 'USA', 'US'];
const US_TEXT = wordsRx(usNames);
const usKey = (s) => String(s).toLowerCase().replace(/\./g, '').replace(/\s+/g, ' ').trim();
const US_KEYS = new Set(usNames.map(usKey));
const metros = (rules.metros || []).map((m) => ({
  cities: wordsRx(m.cities),
  regions: wordsRx(m.regions),
  workplaceTypes: (m.workplaceTypes || []).map((w) => String(w).toLowerCase()),
}));

// "Plano, TX" -> "TX"
function stateCode(text) {
  const m = /,\s*([A-Z]{2})\b/.exec(text || '');
  return m && US_STATES.has(m[1]) ? m[1] : '';
}

function countryOf(p) {
  if (p.country) return US_KEYS.has(usKey(p.country)) ? 'us' : 'other';
  if (has(US_TEXT, p.text) || stateCode(p.text)) return 'us';
  if (has(NON_US_TEXT, p.text)) return 'other';
  return 'unknown';
}

// One location of a posting: "us_remote", "metro", "unclear" or "no".
function placeVerdict(p, workplaceType) {
  const country = countryOf(p);
  if (country === 'other') return 'no';
  const remote = workplaceType === 'remote' || has(REMOTE, p.text);
  if (remote) {
    if (rules.usRemote === false) return 'no';
    return country === 'us' ? 'us_remote' : 'unclear';
  }
  const region = p.region || stateCode(p.text);
  for (const m of metros) {
    const typeOk = !workplaceType || m.workplaceTypes.includes(workplaceType);
    const inCity = has(m.cities, p.locality) || has(m.cities, p.text);
    const regionOk = !region || has(m.regions, region);
    if (inCity && regionOk) return typeOk ? 'metro' : 'no';
  }
  // A location with no city ("Texas", "United States") might still be in a metro.
  const cityKnown = Boolean(p.locality) || /,/.test(p.text);
  const maybeMetro = metros.some((m) =>
    (!workplaceType || m.workplaceTypes.includes(workplaceType)) &&
    (!region || has(m.regions, region) || has(m.regions, p.text)));
  return !cityKnown && maybeMetro ? 'unclear' : 'no';
}

function locationBasis(places, workplaceType) {
  if (!places.length) return 'unclear';
  const verdicts = places.map((p) => placeVerdict(p, workplaceType));
  for (const v of ['us_remote', 'metro', 'unclear']) if (verdicts.includes(v)) return v;
  return '';
}

const EXCLUDED = wordsRx(cfg.excludedTitles);
// A title with one of these words is never excluded: "Software Engineer, Finance Platform".
const OVERRIDES = wordsRx(cfg.excludedTitleOverrides);

return $input.all().map(({ json }) => {
  // Working fields from Normalize postings aren't saved; scoring reads them from that node.
  const { places, description, salary_mentions, ...lead } = json;
  const basis = locationBasis(places || [], String(lead.workplace_type || '').toLowerCase());
  let result = 'passed';
  if (!basis) result = 'location';
  else if (typeof lead.pay_max === 'number' && lead.pay_max < payFloor) result = 'pay_floor';
  else if (has(EXCLUDED, lead.title) && !has(OVERRIDES, lead.title)) result = 'excluded_title';
  return { json: { ...lead, location_basis: basis, filter_result: result } };
});

// One Jev request per lead that needs judging, with all questions in one request.
// A lead is judged only while it can still be sent (New, unsent, passed the filters,
// not closed, inside the freshness window) and only when its scoring input changed:
// the fingerprint hashes the whole request (profile summary, role families, model,
// questions and posting text). Weights, seniority targets and the minimum are applied
// later in code, so changing them needs no new Jev calls.
const cfg = $('Job Scout config').first().json;
const DAY = 24 * 60 * 60 * 1000;
const windowDays = Number(cfg.freshnessWindowDays) || 30;
const NONE = 'None of these';

// Today's postings, with the description and salary mentions that aren't saved.
const postings = new Map($('Normalize postings').all().map((i) => [i.json.lead_key, i.json]));

function ageDays(lead) {
  const times = [lead.published_at, lead.first_seen_at]
    .map((d) => (d ? new Date(d).getTime() : NaN))
    .filter((t) => !isNaN(t));
  return times.length ? (Date.now() - Math.min(...times)) / DAY : 0;
}

// 112-bit string hash (two cyrb53 seeds), so code can tell when the input changed.
function cyrb53(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0');
}
const fingerprintOf = (s) => cyrb53(s, 1) + cyrb53(s, 2);

// Role families come from the config. "None of these" lets Jev say a job fits none.
const families = {};
for (const f of cfg.roleFamilies || []) {
  families[f.name] = { what: f.description || '', example_titles: f.titleKeywords || [] };
}
families[NONE] = {
  what: 'Any other kind of job, such as backend-only, infrastructure, data or security engineering; ' +
    'sales or account management; recruiting; finance; operations; design; or marketing that is not developer relations',
};

const QUESTIONS = {
  role_family: {
    type: 'choice',
    instructions: {
      question: 'Which role family does the job described in `posting` belong to?',
      how_to_judge: 'Judge from `posting.title` and the duties in `posting.description`. ' +
        'Ignore which department or team the job sits in: a developer advocate in a marketing department ' +
        'is still developer relations.',
    },
    criteria: families,
  },
  stack_fit: {
    type: 'score',
    instructions: 'How much of the technology that the job in `posting` works with is in the candidate\'s skills in `profile.summary`?',
    criteria: [
      'None of the languages, frameworks or platforms the job uses are in the candidate\'s skills',
      'Only minor tools overlap; the job\'s main languages and frameworks are different',
      'Some core technologies overlap, but a main language or framework is different',
      'Most of the job\'s core languages and frameworks are in the candidate\'s skills',
      'The job\'s technology is essentially the candidate\'s skills',
    ],
  },
  names_stack: {
    type: 'noul',
    instructions: 'Does `posting.description` name specific programming languages, frameworks or technical platforms used in this job?',
  },
  seniority: {
    type: 'choice',
    instructions: 'What seniority level is the job in `posting`, based on `posting.title` and `posting.description`?',
    criteria: {
      intern_junior: 'Intern, new graduate, junior or associate level',
      mid: 'Mid-level individual contributor, with no senior, lead or staff title',
      senior: 'Senior individual contributor, such as Senior Engineer or Senior Developer Advocate',
      lead: 'Lead individual contributor or team lead, such as Lead Engineer, Tech Lead or a title ending in Lead',
      staff_plus: 'Staff, principal or distinguished individual contributor',
      manager: 'Manages people or a function: engineering manager, head of a team, director or VP',
      founding: 'Founding or first hire on a team, such as Founding Engineer',
      not_stated: 'The title and description don\'t indicate a level',
    },
  },
  domain_fit: {
    type: 'score',
    instructions: 'How closely do the product area and the users of the job in `posting` match the domains in `profile.summary`?',
    criteria: [
      'Unrelated to any domain in the candidate\'s profile',
      'Loosely related: a different product area, with some transferable context',
      'Adjacent: a closely related product area or the same kind of users',
      'The same domain the profile names, such as the same kind of product and users',
    ],
  },
};

// Only for postings with no structured pay: Jev picks the base salary among the dollar
// amounts a regex found in the description, or none. Code compares it with the floor.
function payQuestion(mentions) {
  const criteria = {};
  for (const m of mentions) criteria[m.span] = null;
  criteria.none = 'None of these is the job\'s base salary: they are funding, revenue, customer size, benefits, ' +
    'equity, bonus, commission or other amounts';
  return {
    type: 'choice',
    instructions: 'Which of these amounts is the base salary or base salary range for the job in `posting`, ' +
      'in US dollars per year? `posting.pay_mentions` shows where each amount appears.',
    criteria,
  };
}

const out = [];
for (const { json: lead } of $input.all()) {
  if (!lead.lead_key || lead.closed_at) continue;
  if (ageDays(lead) > windowDays) continue;
  const p = postings.get(lead.lead_key);
  if (!p) continue; // not in today's fetch: its board failed or the posting is gone

  const location = [p.location_text, p.workplace_type, p.secondary_locations && 'also: ' + p.secondary_locations]
    .filter(Boolean).join(' · ');
  const posting = {
    title: p.title,
    company: p.company,
    location: location || 'Not stated',
    pay: p.pay_text || 'Not stated',
    description: p.description || '',
  };
  const questions = { ...QUESTIONS };
  const mentions = p.pay_min == null && p.pay_max == null ? p.salary_mentions || [] : [];
  if (mentions.length) {
    posting.pay_mentions = mentions.map((m) => m.context);
    questions.base_salary = payQuestion(mentions);
  }
  const body = {
    model: cfg.jevModel,
    state: {
      profile: { summary: cfg.profileSummary, role_families: (cfg.roleFamilies || []).map((f) => f.name) },
      posting,
    },
    questions,
  };
  const fingerprint = fingerprintOf(JSON.stringify(body));
  if (lead.scoring_state === 'scored' && lead.scoring_fingerprint === fingerprint) continue;
  out.push({ json: { id: lead.id, lead_key: lead.lead_key, scoring_fingerprint: fingerprint, jev_body: body } });
}

// A fixed order, so test fixtures can line up with the requests.
out.sort((a, b) => (a.json.lead_key < b.json.lead_key ? -1 : 1));
return out;

// Turns each Jev response into stored judgments, each normalized to 0-1:
//   sub_role_family: the probability that the job is in one of the configured families
//   sub_stack:       stack overlap; when the posting names no stack, it counts as 0.5
//   sub_domain:      domain overlap
// The seniority answer is stored and turned into a sub-score in Score and select, so
// changing targetSeniority needs no new Jev calls. A response without valid answers
// (the request failed after its retries) leaves the lead unscored: it isn't sent, and
// it is judged again on the next scan.
const requests = $('Build Jev requests').all();
const responses = $input.all();
if (requests.length !== responses.length) {
  throw new Error(`Jev returned ${responses.length} responses for ${requests.length} requests`);
}
const NONE = 'None of these';
const round = (n, d = 3) => Math.round(n * 10 ** d) / 10 ** d;
const probs = (p) => Object.fromEntries(Object.entries(p || {}).map(([k, v]) => [k, round(v)]));
const top = (q) => q.criteria.length - 1;

// "$150,000 - $190,000" or "$160K–$200K" -> [150000, 190000]
function amounts(span) {
  return (span.match(/\d[\d,]*(?:\.\d+)?\s?[kK]?/g) || []).map((a) => {
    const n = parseFloat(a.replace(/,/g, ''));
    return /k$/i.test(a.trim()) ? n * 1000 : n;
  });
}

return responses.map((item, i) => {
  const req = requests[i].json;
  const q = req.jev_body.questions;
  const a = (item.json && item.json.answers) || {};
  const valid = ['role_family', 'stack_fit', 'names_stack', 'seniority', 'domain_fit']
    .concat(q.base_salary ? ['base_salary'] : [])
    .every((id) => a[id] && a[id].type === q[id].type);
  if (!valid) return { json: { id: req.id, scoring_state: 'unscored' } };

  const namesStack = a.names_stack.noul;
  const stack = namesStack * (a.stack_fit.score / top(q.stack_fit)) + (1 - namesStack) * 0.5;
  let pay = { text: null, min: null, max: null };
  if (a.base_salary && a.base_salary.choice !== 'none') {
    const values = amounts(a.base_salary.choice);
    pay = { text: a.base_salary.choice, min: Math.min(...values), max: Math.max(...values) };
  }
  const answers = {
    role_family: { choice: a.role_family.choice, confidence: round(a.role_family.confidence), p: probs(a.role_family.probabilities) },
    stack_fit: { score: round(a.stack_fit.score), confidence: round(a.stack_fit.confidence) },
    names_stack: { noul: round(namesStack) },
    seniority: { choice: a.seniority.choice, confidence: round(a.seniority.confidence), p: probs(a.seniority.probabilities) },
    domain_fit: { score: round(a.domain_fit.score), confidence: round(a.domain_fit.confidence) },
  };
  if (a.base_salary) answers.base_salary = { choice: a.base_salary.choice, confidence: round(a.base_salary.confidence) };

  return {
    json: {
      id: req.id,
      scoring_state: 'scored',
      scoring_fingerprint: req.scoring_fingerprint,
      scored_at: new Date().toISOString(),
      jev_model: item.json.model || req.jev_body.model,
      jev_answers: JSON.stringify(answers),
      role_family: a.role_family.choice,
      seniority_level: a.seniority.choice,
      sub_role_family: round(1 - ((a.role_family.probabilities || {})[NONE] || 0)),
      sub_stack: round(stack),
      sub_domain: round(a.domain_fit.score / top(q.domain_fit)),
      pay_extracted_text: pay.text,
      pay_extracted_min: pay.min,
      pay_extracted_max: pay.max,
    },
  };
});

// Fit score for every candidate lead, recomputed on every scan from the stored Jev
// judgments and the current config, so a weight change re-ranks leads with no new
// Jev calls. Code adds the sub-scores Jev doesn't judge:
//   seniority: 1 for a level in targetSeniority, 0.5 when the posting states no level,
//              0.2 for any other level (weighted by Jev's probability for each level)
//   location:  1 for US-remote or a configured metro, 0.5 for "Location unclear"
//   freshness: 1 when first seen or published today, falling to 0 at the window's end
//   referral:  0 until referrals exist
// Each sub-score (0-1) times its weight, scaled so all weights add up to 100, is its
// points, and the fit score is the sum of the points. A lead can be sent when it is
// scored, passed the filters, New, unsent, not closed, inside the freshness window and
// at or above minFitScore.
const cfg = $('Job Scout config').first().json;
const DAY = 24 * 60 * 60 * 1000;
const windowDays = Number(cfg.freshnessWindowDays) || 30;
const minFit = Number(cfg.minFitScore) || 0;
const payFloor = Number(cfg.payFloor) || 0;
const target = new Set((cfg.targetSeniority || []).map((s) => String(s).toLowerCase()));
const LOCATION = { us_remote: 1, metro: 1, unclear: 0.5 };
const DIMENSIONS = ['roleFamily', 'stack', 'seniority', 'location', 'domain', 'freshness', 'referral'];
const weights = cfg.weights || {};
const totalWeight = DIMENSIONS.reduce((s, d) => s + (Number(weights[d]) || 0), 0) || 1;
const round = (n, d = 3) => Math.round(n * 10 ** d) / 10 ** d;

// New judgments from this scan, by row id.
const judged = new Map();
if ($('Read Jev answers').isExecuted) {
  for (const { json } of $('Read Jev answers').all()) judged.set(json.id, json);
}

function ageDays(lead) {
  const times = [lead.published_at, lead.first_seen_at]
    .map((d) => (d ? new Date(d).getTime() : NaN))
    .filter((t) => !isNaN(t));
  return times.length ? (Date.now() - Math.min(...times)) / DAY : 0;
}

function seniorityScore(lead) {
  let p = {};
  try {
    p = JSON.parse(lead.jev_answers || '{}').seniority.p || {};
  } catch (e) {
    p = {};
  }
  const value = (level) => (target.has(level) ? 1 : level === 'not_stated' ? 0.5 : 0.2);
  const entries = Object.entries(p);
  if (!entries.length) return value(lead.seniority_level);
  return entries.reduce((s, [level, prob]) => s + prob * value(level), 0);
}

return $('Get candidate leads').all().filter((i) => i.json.lead_key).map(({ json: row }) => {
  const lead = { ...row, ...(judged.get(row.id) || {}) };
  const age = ageDays(lead);
  const sub = {
    roleFamily: lead.sub_role_family,
    stack: lead.sub_stack,
    seniority: seniorityScore(lead),
    location: LOCATION[lead.location_basis] ?? 0,
    domain: lead.sub_domain,
    freshness: Math.max(0, 1 - age / windowDays),
    referral: 0,
  };

  // Pay stated only in the description: Jev picked the span, code checks the floor.
  let filterResult = lead.filter_result;
  if (lead.pay_min == null && lead.pay_max == null && typeof lead.pay_extracted_max === 'number' &&
      lead.pay_extracted_max < payFloor) {
    filterResult = 'pay_floor';
  }

  const scored = lead.scoring_state === 'scored';
  let points = null;
  let fit = null;
  if (scored) {
    points = {};
    for (const d of DIMENSIONS) points[d] = Math.round((100 * (Number(weights[d]) || 0) * (sub[d] || 0)) / totalWeight);
    fit = DIMENSIONS.reduce((s, d) => s + points[d], 0);
  }

  const eligible = scored && filterResult === 'passed' && lead.status === 'new' && !lead.sent_at &&
    !lead.closed_at && age <= windowDays && fit >= minFit;
  return {
    json: {
      ...lead,
      filter_result: filterResult,
      sub_seniority: round(sub.seniority),
      sub_location: sub.location,
      sub_freshness: round(sub.freshness),
      sub_referral: sub.referral,
      fit_score: fit,
      points,
      eligible,
    },
  };
});

// Today's ping: eligible leads, highest fit score first, up to dailyCap. Ties go to the
// newer posting. Leads that miss the cap stay New and compete again on the next scan.
// Each picked lead carries its posting description for the fit line.
const cfg = $('Job Scout config').first().json;
const cap = Math.max(0, Number(cfg.dailyCap) || 0);
const descriptions = new Map($('Normalize postings').all().map((i) => [i.json.lead_key, i.json.description]));
const time = (d) => (d ? new Date(d).getTime() : 0);

return $('Score and select').all()
  .map((i) => i.json)
  .filter((lead) => lead.eligible)
  .sort((a, b) => b.fit_score - a.fit_score || time(b.published_at) - time(a.published_at) ||
    (a.lead_key < b.lead_key ? -1 : 1))
  .slice(0, cap)
  .map((lead) => ({ json: { ...lead, description: descriptions.get(lead.lead_key) || '' } }));

